const LANGUAGE_STORAGE_KEY = "chiraq_language";
const validLanguageIds = new Set(LANGUAGE_OPTIONS.map(({ id }) => id));

function readLanguage() {
  try {
    const stored = globalThis.localStorage?.getItem(LANGUAGE_STORAGE_KEY);
    return validLanguageIds.has(stored) ? stored : "az";
  } catch {
    return "az";
  }
}

let activeLanguage = readLanguage();
const LanguageContext = createContext({ language: "az", setLanguage: () => {} });

export function translate(source, values = {}) {
  let template = translations[activeLanguage]?.[source];
  if (!template && typeof source === "string") {
    const cityQuestion = source.match(/^(.+?) hansı şəhərdə yerləşir\?$/);
    if (cityQuestion && activeLanguage !== "az") {
      const placeName = translations[activeLanguage]?.[cityQuestion[1]] || cityQuestion[1];
      template = activeLanguage === "en" ? `Which city is ${placeName} located in?` : `В каком городе находится ${placeName}?`;
    }
    const firstCapture = source.match(/^(.+?) ilk dəfə fəth etdin!$/);
    const captureWithRival = source.match(/^(.+?) (.+)-dan fəth etdin!$/);
    if (!template && activeLanguage !== "az" && (firstCapture || captureWithRival)) {
      const placeNameAz = (firstCapture || captureWithRival)[1];
      const placeName = translations[activeLanguage]?.[placeNameAz] || translations[activeLanguage]?.[placeNameAz.replace(/ məkanını$/, "")] || placeNameAz;
      if (firstCapture) template = activeLanguage === "en" ? `You captured ${placeName} for the first time!` : `Ты впервые захватил место «${placeName}»!`;
      else {
        const university = captureWithRival[2];
        template = activeLanguage === "en" ? `You captured ${placeName} from ${university}!` : `Ты захватил место «${placeName}» у ${university}!`;
      }
    }
  }
  template ||= source;
  return template.replace(/\{(\w+)\}/g, (match, name) => values[name] == null ? match : String(values[name]));
}

export function LanguageProvider({ children }) {
  const [language, setLanguageState] = useState(readLanguage);
  const setLanguage = useCallback((nextLanguage) => {
    if (!validLanguageIds.has(nextLanguage)) return;
    activeLanguage = nextLanguage;
    setLanguageState(nextLanguage);
    try { globalThis.localStorage?.setItem(LANGUAGE_STORAGE_KEY, nextLanguage); } catch { /* Language still changes for this session. */ }
  }, []);
  return createElement(LanguageContext.Provider, { value: { language, setLanguage } }, children);
}

export function useI18n() {
  return useContext(LanguageContext);
}
